INSERT INTO "decisions" (rowid, "decision_id", "category", "delegation", "delegation_rationale", "summary", "outcome", "rationale", "decision_date", "decided_by", "model_routing", "effort_level", "status", "review_status", "supersedes", "predecessors", "decision_artifacts", "alternatives_considered", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (5, 'D-0005', 'D-DOCT', 'DG-NON', NULL, 'Best practice means the most accommodating, thoughtful, respectful, dignified, and usable condition achievable for th...', 'Best practice means the most accommodating, thoughtful, respectful, dignified, and usable condition achievable for th...', 'Best practice means the most accommodating, thoughtful, respectful, dignified, and usable condition achievable for the disabled person. Best practice is determined by the evidence hierarchy — Tier 1 clinical research, Co-1 lived experience, Co-2 OT CPGs, Tier 3 systematic reviews — not by code consensus. Codes are Tier 6: the compliance floor, not the aspiration. Code consensus across jurisdictions establishes what most codes agree on; it does not establish what is most accommodating or most dignified. A BPC best_practice_synthesis that derives its value solely from code consensus is in error. The test: does this specification provide the most accommodating, dignified, usable condition the evidence supports — or does it merely reflect what codes agree on?', '2026-04-24 23:46', 'solo_author_pre_launch', 'legacy/none/none', 100, 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md \u00a7Core Doctrine (locked)"]', '["(seeded record; original alternatives not captured at rule authoring; reviewable)"]', 'Seeded from project-standards.md §Core Doctrine (locked) at A12 Session 2 (2026-04-30 13:20). Classification heuristic; review pending.', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import', '2026-08-04 19:55', 'session_2026-08-04-f3a-decision-register-import');

